 private void loadTechnicalIndicators(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"2y","1d",520);if(d==null||d.size()<60)return;int n=d.size(),e=n-1;double price=d.get(e).close,g=0,l=0,hi=-1e99,lo=1e99,tp=0,md=0,tr=0;for(int i=n-14;i<n;i++){double z=d.get(i).close-d.get(i-1).close;if(z>=0)g+=z;else l-=z;hi=Math.max(hi,d.get(i).high);lo=Math.min(lo,d.get(i).low);tp+=(d.get(i).high+d.get(i).low+d.get(i).close)/3d;tr+=Math.max(d.get(i).high-d.get(i).low,Math.max(Math.abs(d.get(i).high-d.get(i-1).close),Math.abs(d.get(i).low-d.get(i-1).close)));}double rsi=100-(100/(1+(l==0?100:g/l))),stoch=hi==lo?50:100*(price-lo)/(hi-lo),mtp=tp/14d;for(int i=n-14;i<n;i++)md+=Math.abs((d.get(i).high+d.get(i).low+d.get(i).close)/3d-mtp);md/=14d;double cci=md==0?0:(((d.get(e).high+d.get(e).low+price)/3d)-mtp)/(0.015*md),ema20=ema(d,20,e),ema50=ema(d,50,e),ema200=ema(d,200,e),macd=ema(d,12,e)-ema(d,26,e),atr=tr/14d;ShortPulseEngine.Result p=ShortPulseEngine.analyze(d,symbol,selectedProfile);String rows=String.format(java.util.Locale.GERMANY,"RSI(14)        %.1f   %s\nMACD           %.2f   %s\nStochastic     %.1f   %s\nCCI            %.1f   %s\nEMA20          %.2f   %s\nEMA50          %.2f   %s\nEMA200         %.2f   %s\nATR(14)        %.2f\nBRTV           %.1f\nBRM            %.2f\nBRH            %.1f",rsi,rsi<35?"AL":rsi>70?"SAT":"İZLE",macd,macd>0?"AL":"SAT",stoch,stoch<25?"AL":stoch>80?"SAT":"İZLE",cci,cci>100?"AL":cci<-100?"SAT":"İZLE",ema20,price>ema20?"AL":"SAT",ema50,price>ema50?"AL":"SAT",ema200,price>ema200?"AL":"SAT",atr,p.brtv,p.brm,p.brh);String sum=String.format(java.util.Locale.GERMANY,"Genel Teknik Görünüm: %s\nPulse %.1f • Güven %.0f%%\n%s",p.recommendation,p.score,p.confidence,p.phaseText);runOnUiThread(()->{if(!symbol.equals(selectedSymbol))return;if(technicalRows!=null)technicalRows.setText(rows);if(technicalSummary!=null){technicalSummary.setText(sum);technicalSummary.setTextColor(p.recommendation.contains("AL")?GREEN:p.recommendation.contains("SAT")?RED:AMBER);}});}catch(Exception ex){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&technicalRows!=null)technicalRows.setText("Teknik veriler hesaplanamadı");});}});}
 private void loadTargetRisk(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"2y","1d",520);if(d==null||d.size()<60)return;int n=d.size(),e=n-1,start=Math.max(1,n-252);double price=d.get(e).close,hi=-1e99,lo=1e99,tr=0,sum=0,w=0;for(int i=start;i<n;i++){MarketDataService.Candle x=d.get(i);hi=Math.max(hi,x.high);lo=Math.min(lo,x.low);double wt=1d+(i-start)/(double)Math.max(1,n-start);sum+=x.close*wt;w+=wt;if(i>=n-14)tr+=Math.max(x.high-x.low,Math.max(Math.abs(x.high-d.get(i-1).close),Math.abs(x.low-d.get(i-1).close)));}MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)price=sp.price;double atr=tr/14d;ShortPulseEngine.Result pulse=ShortPulseEngine.analyze(d,symbol,selectedProfile);double adj=Math.max(-.12,Math.min(.12,(pulse.score-50d)/250d)),paper=Math.max(lo,Math.min(hi,(sum/w)*(1+adj)));double support=Math.max(lo,price-2*atr),resistance=Math.min(hi,price+2*atr),stop=Math.max(lo,price-2.5*atr),t1=Math.max(price+atr,paper),t2=Math.max(t1,Math.min(hi,price+3*atr));double rr=(price-stop)<=0?0:(t1-price)/(price-stop),gap=price==0?0:(paper/price-1)*100;String txt=String.format(java.util.Locale.GERMANY,"Güncel          %.2f%s\nKağıt değeri    %.2f%s  (%+.1f%%)\nDestek          %.2f%s\nDirenç          %.2f%s\nHedef 1         %.2f%s\nHedef 2         %.2f%s\nStop referansı  %.2f%s\nATR(14)         %.2f\nRisk/Getiri     1 : %.2f\n\nBorsaPulse: %s • %.0f%% güven",price,currency(symbol),paper,currency(symbol),gap,support,currency(symbol),resistance,currency(symbol),t1,currency(symbol),t2,currency(symbol),stop,currency(symbol),atr,rr,pulse.recommendation,pulse.confidence);runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&targetRiskData!=null){targetRiskData.setText(txt);targetRiskData.setTextColor(gap>=12?GREEN:gap<=-10?RED:Color.WHITE);}});}catch(Exception ex){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&targetRiskData!=null)targetRiskData.setText("Hedef/risk verisi hesaplanamadı");});}});}
