 private void loadChartQuote(){final String symbol=selectedSymbol;uiIo.execute(()->{try{java.util.List<MarketDataService.Candle>d=MarketDataService.fetchSeries(symbol,"5d","5m",400);if(d==null||d.size()<2)return;MarketDataService.Candle last=d.get(d.size()-1),prev=d.get(d.size()-2);double spot=last.close;MarketDataService.Spot sp=MarketDataService.latestSpot(symbol);if(sp!=null&&sp.price>0)spot=sp.price;final double price=spot,chg=spot-prev.close,pct=prev.close==0?0:(chg/prev.close*100d);runOnUiThread(()->{if(!symbol.equals(selectedSymbol)||chartPrice==null)return;chartPrice.setText(String.format(java.util.Locale.GERMANY,"%.2f%s",price,currency(symbol)));chartChange.setText(String.format(java.util.Locale.GERMANY,"%+.2f  (%+.2f%%)",chg,pct));chartChange.setTextColor(chg>=0?GREEN:RED);});}catch(Exception e){runOnUiThread(()->{if(symbol.equals(selectedSymbol)&&chartPrice!=null)chartPrice.setText("Fiyat alınamadı");});}});}
 private void setLiveStats(double[] v){if(liveStats==null)return;liveStats.removeAllViews();String[] ss;if(v==null)ss=new String[]{"Açılış\n—","Yüksek\n—","Düşük\n—","Hacim\n—"};else ss=new String[]{String.format(java.util.Locale.GERMANY,"Açılış\n%.2f",v[0]),String.format(java.util.Locale.GERMANY,"Yüksek\n%.2f",v[1]),String.format(java.util.Locale.GERMANY,"Düşük\n%.2f",v[2]),"Hacim\n"+formatVolume(v[3])};for(String s:ss){TextView x=t(s,9,Color.WHITE,false);x.setGravity(Gravity.CENTER);liveStats.addView(x,new LinearLayout.LayoutParams(0,dp(48),1));}}
 private String formatVolume(double v){if(v>=1000000000)return String.format(java.util.Locale.GERMANY,"%.1f Mr",v/1000000000d);if(v>=1000000)return String.format(java.util.Locale.GERMANY,"%.1f M",v/1000000d);if(v>=1000)return String.format(java.util.Locale.GERMANY,"%.1f B",v/1000d);return String.format(java.util.Locale.GERMANY,"%.0f",v);}
 private void syncRadarIndex(){for(int i=0;i<radarSymbols.length;i++)if(radarSymbols[i].equals(selectedSymbol)){radarIndex=i;return;}}
